export default function AsideNav({isNavOpen,setIsNavOpen}){


     {/* nav bar is a humburger menue , overlayered in the mobile , aside otherwise */}

  return(  <aside className=  {`  2xl:w-[360px]  xl:w-[248px]  md:w-20 w-11/12  min-h-screen  absolute md:static left-0 top-0 bg-sidenav-bg transform 
    ${isNavOpen?'translate-x-0':'-translate-x-full'} md:translate-x-0 transition-transform duration-300 ease-in-out
    z-20`} >

      {/* logo and name */}
      
       < div className='px-6 py-4 mx-auto flex  items-center 
md:justify-center  justify-between' >
 <div className='flex gap-2 items-center 
md:justify-center '>
  <img src={sfg} alt="logo" />
  <span className='text-white text-xl font-semibold md:hidden xl:block' > SFG group</span>
</div>

 <div>
  <img src={cross} alt="close" className='md:hidden cursor-pointer w-6 h-6 ' onClick={()=>setIsNavOpen(false)}/>
  </div>

            </div> 

           <AsideLinks navLinks={navLinks}/>
  
  

                    <div>
  
             </div>
             </aside>
  );
}